const webhook   = $('Webhook').first().json.body;
const deal      = $('Get General Deal').first().json.data || {};
const bankDeal  = $('Get Bank Deal').first().json.data || {};

const dealId     = webhook.deal_id;
const bankDealId = webhook.bank_deal_id;
const zipFileId  = webhook.zip_file_id || '';
const zipLink    = webhook.zip_drive_link || '';

// Basic client fields — fallback to webhook if deal not available
const nombre = webhook.nombre_cliente || deal.person_name || '';
const dni    = webhook.dni || deal['60228dc43313b931378ec9bb3f21f7ad7f5a144c'] || '';
const plan   = webhook.plan || deal['b5d36c005e38a4cd72d831be655996a3d6b34dc1'] || '';

// Email routing
// KUTXABANK_EMAIL env var = production mailbox; fallback = test
const toEmail  = $env.KUTXABANK_EMAIL || 'juan.tamayo@huspy.io';
const bccList  = [
  `mdsl+deal${dealId}@pipedrivemail.com`,
  `mdsl+deal${bankDealId}@pipedrivemail.com`
].join(',');

const subject  = `Kutxabank - Nuevo Expediente - ${bankDealId} - ${plan} - ${nombre} - DNI ${dni}`;

// ── Enum maps (same field IDs as CR Teruel) ─────────────────────────────────
const mortgageMap = {
  1458: 'Fija', 1459: 'Variable', 1460: 'Mixta',
  2451: 'Fija y Mixta', 2452: 'Variable y Mixta',
  2453: 'Fija y Variable', 2454: 'Fija, Mixta y Variable'
};
const compraMap = {
  2547: 'Primera residencia', 2548: 'Segunda residencia', 2549: 'Inversión',
  2550: 'Cambio de hipoteca', 2551: 'Extinción de condominio', 2552: 'Autopromoción'
};
const contractType1Map = {
  2613: 'Indefinido', 2614: 'Funcionario', 2615: 'Autónomo', 2616: 'Temporal',
  2617: 'Interino', 2618: 'Fijo discontínuo', 2619: 'Desempleado',
  2620: 'Jubilado', 2863: 'Pensionista'
};
const maritalStatus1Map = {
  2621: 'Soltero', 2622: 'Casado en Gananciales',
  2623: 'Casado en Separación de bienes', 2624: 'Viudo', 2625: 'Divorciado'
};
const contractType2Map = {
  2526: 'Indefinido', 2527: 'Funcionario', 2528: 'Autónomo', 2529: 'Temporal',
  2530: 'Desempleado', 2531: 'Interino', 2532: 'Fijo discontínuo', 2864: 'Pensionista'
};
const maritalStatus2Map = {
  2533: 'Soltero', 2534: 'Casado en Gananciales',
  2535: 'Casado en Separación de bienes', 2536: 'Viudo', 2537: 'Divorciado'
};
const provinceEnumMap = {
  2553: 'Albacete', 2554: 'Alicante/Alacant', 2555: 'Almería', 2556: 'Araba/Álava',
  2557: 'Asturias', 2558: 'Ávila', 2559: 'Badajoz', 2560: 'Balears, Illes',
  2561: 'Barcelona', 2562: 'Bizkaia', 2563: 'Burgos', 2564: 'Cáceres',
  2565: 'Cádiz', 2566: 'Cantabria', 2567: 'Castellón/Castelló', 2568: 'Ciudad Real',
  2569: 'Córdoba', 2570: 'Coruña, A', 2571: 'Cuenca', 2572: 'Gipuzkoa',
  2573: 'Girona', 2574: 'Granada', 2575: 'Guadalajara', 2576: 'Huelva',
  2577: 'Huesca', 2578: 'Jaén', 2579: 'León', 2580: 'Lleida', 2581: 'Lugo',
  2582: 'Madrid', 2583: 'Málaga', 2584: 'Murcia', 2585: 'Navarra',
  2586: 'Ourense', 2587: 'Palencia', 2588: 'Palmas, Las', 2589: 'Pontevedra',
  2590: 'Rioja, La', 2591: 'Salamanca', 2592: 'Santa Cruz de Tenerife',
  2593: 'Segovia', 2594: 'Sevilla', 2595: 'Soria', 2596: 'Tarragona',
  2597: 'Teruel', 2598: 'Toledo', 2599: 'Valencia/València', 2600: 'Valladolid',
  2601: 'Zamora', 2602: 'Zaragoza', 2603: 'Ceuta', 2604: 'Melilla',
  2605: 'Canarias', 3052: 'Vitoria', 3053: 'Oviedo', 3113: 'TBC'
};

const resolveEnum = (rawValue, map) => {
  if (!rawValue && rawValue !== 0) return '-';
  const key = typeof rawValue === 'object' ? (rawValue.id ?? rawValue.value) : rawValue;
  return map[Number(key)] || String(rawValue);
};

// ── Field resolution ─────────────────────────────────────────────────────────
const tipoHip      = resolveEnum(deal['9663fa3058468da182be6afbf71a501b8c9fb89e'], mortgageMap);
const tipoComp     = resolveEnum(deal['bc2fb38a576f000bd311e49d4da2dd20dbf9439b'], compraMap);
const contrato1    = resolveEnum(deal['5788be4f764dabff9006ab5d685ae8061c7db3d9'], contractType1Map);
const estadoCivil1 = resolveEnum(deal['94162c8595944c684ec0e62dd8f8f5bfde30f7d1'], maritalStatus1Map);
const contrato2    = resolveEnum(deal['9d6bb0a4cffae14651df0370331afa40b101c6e9'], contractType2Map);
const estadoCivil2 = resolveEnum(deal['b51dfe92bec2db54fbf8f3849e642d20449cc807'], maritalStatus2Map);
const provincia    = resolveEnum(deal['15edcbc34620af8067c2413c2d9793b2a6bba3ba'], provinceEnumMap);

const importeBanco = bankDeal['b80d8ee37cc14ecdd7d8a640a57d6bd85308d5b9'] || deal['b80d8ee37cc14ecdd7d8a640a57d6bd85308d5b9'] || '';

// ── Segundo titular ──────────────────────────────────────────────────────────
const segundoTitularNombre = deal['209a0da7966a29bf05e96b6a124536222e0318dd'] || '';

const seccionSegundoTitular = segundoTitularNombre ? `
<p>👤 <strong>Datos 2do titular:</strong></p>
<p>
Nombre: ${segundoTitularNombre}<br>
DNI: ${deal['c83f49f1e2fd08f55a16b159dd88802d2b5baa04'] || '-'}<br>
Correo electrónico: ${deal['43cad7dea8c1b587f141432e1a3965260ae6e0cb'] || '-'}<br>
