Deudas mensuales: ${deal['eeb214b68e7334f31d6254f42ee39fd2967f8e44'] || '-'} €<br>
Tipo de contrato: ${contrato2}<br>
Antigüedad laboral: ${deal['7b9c465c402175d6b8aaf029007ec3807495e806'] || '-'}<br>
Estado civil: ${estadoCivil2}
</p>` : '';

// ── HTML body ────────────────────────────────────────────────────────────────
const body = `<p>Buenos días.</p>
<p>Compartimos el dossier completo de un cliente interesado en obtener una hipoteca con Kutxabank. A continuación, detallamos los datos principales.</p>

<p><strong>⚠️ IMPORTANTE:</strong> Los documentos se adjuntan en un archivo ZIP encriptado con contraseña.<br>
La contraseña es el <strong>DNI del titular: ${dni}</strong></p>

<p>Resumen: ${deal['de65f08f768d5985a623e6a05e033ac55b4781eb'] || ''}</p>

<p>👤 <strong>Datos 1er titular:</strong></p>
<p>
Nombre: ${deal.person_name || nombre}<br>
Edad: ${deal['603fc04228fa5186ffc181e33b239a716a70078c'] || '-'}<br>
DNI: ${dni}<br>
Correo electrónico: ${deal['7708e6e9db2709552beafef5fda4929298d71417'] || '-'}<br>
Teléfono: ${deal['95abb5a0541d1b72ffbe2f1abefc5464f6421e3b'] || '-'}<br>
Ingresos mensuales: ${deal['8e0e7ac2bd665bc3c0c5eb7d979a1ae1d9bc1300'] || '-'} €<br>
Deudas mensuales: ${deal['d36439696132252825354878c99d027a3af2d553'] || '-'} €<br>
Tipo de contrato: ${contrato1}<br>
Antigüedad laboral: ${deal['be0f811d86cd2f929e602b57b0745ca59fcbf73e'] || '-'}<br>
Estado civil: ${estadoCivil1}
</p>

${seccionSegundoTitular}

<p>🏠 <strong>Datos de la operación:</strong></p>
<p>
Importe de compraventa: ${deal['184fc13001dbca74b20c77f0fcfdec161b5cb492'] || '-'} €<br>
Importe solicitado: ${importeBanco} €<br>
Ahorros / contribución inicial: ${deal['c5f5be52374084fe506fcab9870b296e4ff4f494'] || '-'} €<br>
Provincia: ${provincia}<br>
Dirección del inmueble: ${deal['51edb7d9fe7a23d2ff47bfd802068172cf20e61b'] || '-'}<br>
Tipo de compra: ${tipoComp}<br>
Tipo de hipoteca solicitada: ${tipoHip}<br>
Plazo: ${deal['718ded557b843ad6ec94558a1da186ca063b11ee'] || '-'} años
</p>

<p>Quedamos atentos.<br>Muchas gracias,<br>Saludos</p>`;

// Note for Pipedrive
const noteContent = `📧 Expediente enviado a Kutxabank\nDeal Banco: #${bankDealId}\nAsunto: ${subject}${zipLink ? `\n📎 ZIP Drive: ${zipLink}` : ''}`;

return [{ json: { toEmail, bccList, subject, body, noteContent, zipFileId } }];

// Combine ZIP binary with email JSON data
const emailData = $('Prepare Email').first().json;
const zipItem   = $input.first();

// The Google Drive download node puts the file in binary
const zipBinary = Object.values(zipItem.binary || {})[0] || null;

const binary = {};
if (zipBinary) {
  // Rename the binary to 'zip' so Gmail node can reference it
  binary['zip'] = zipBinary;
}

return [{ json: { ...emailData }, binary }];
